// Changes phase with the same control that changes pulse-width as seen in Lumen.

#define uv (gl_FragCoord.xy/iResolution.xy)
#define time iTime
#define speed .5

float freq = 2.0;
float pw = 0.5; // -> (0. - 0.5) = 0% - 50% // (0.5 - 1.) = phase offset // (1. - 1.5) = 50% - 0%

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

     //--Palindrome Animation--
          pw = abs(mod(time * speed, 3.0) - 1.5); // -> Comment or Erase.

    float th1 = clamp(pw, 0.5, 1.0);
    float th2 = clamp(pw, 1.0, 1.5);
    float th3 = clamp(pw, 0.0, 0.5);

    float phaseOff = (uv.x * freq) - th1;
    float sawtooth = fract(phaseOff);

    float pw1 = 1.0-step(sawtooth, th2-1.0);
    float pw2 = step(sawtooth, th3);

    float wave = pw1*pw2;

   fragColor = vec4(vec3(wave), 1.0);


    //---1D Waveform Overlay---
    float scope = step(fract(-uv.y+wave*0.5-0.75), 0.025); 
    vec4 waveScopeMix = wave-vec4(vec3(scope),1.0);
         waveScopeMix = clamp(waveScopeMix, 0.0, 1.0);
         waveScopeMix = waveScopeMix+vec4(0,scope,0,1);

    fragColor = waveScopeMix;
    //------------------------

}
